// recipe: heart-rate-set
// args: value=n
// returns: ok, before, after, error, detail
//
// Sets the LOCAL body's own heart rate, so a batch can put a patient into cardiac arrest without waiting for a real
// exsanguination. `Body.inCardiacArrest` is exactly `heartRate < 20` (reversing/Assembly-CSharp/Assembly-CSharp/Body.cs:183-188),
// and the panel's flatline edge reads that property on the DISPLAYED body, so this is the one input that makes the edge
// testable from the outside. The field is written directly because the game has no setter and the circulation pass recomputes it
// from blood oxygen on its own schedule; the next snapshot carries the value, which is what the viewer's panel reads.
//
// ONE LINE ON PURPOSE: the client's evaluator takes one top-level expression.
((System.Func<string>)(() => { var value = (float)({{n:value}}); var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); var cameraType = (System.Type)null; for (var i = 0; i < assemblies.Length; i++) { try { cameraType = assemblies[i].GetType("PlayerCamera", false); } catch { cameraType = null; } if (cameraType != null) { break; } } if (cameraType == null) { return "{\"ok\":false,\"error\":\"no-camera-type\"}"; } var staticFlags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var cameraProperty = cameraType.GetProperty("main", staticFlags); var cameraField = cameraType.GetField("main", staticFlags); var instance = cameraProperty != null ? cameraProperty.GetValue(null, null) : cameraField != null ? cameraField.GetValue(null) : null; if (instance == null) { return "{\"ok\":false,\"error\":\"no-camera\"}"; } var bodyField = cameraType.GetField("body", flags); var body = bodyField == null ? null : bodyField.GetValue(instance); if (body == null) { return "{\"ok\":false,\"error\":\"no-body\"}"; } var bodyType = body.GetType(); var rateField = bodyType.GetField("heartRate", flags); if (rateField == null) { return "{\"ok\":false,\"error\":\"no-heart-rate-field\"}"; } var before = System.Convert.ToSingle(rateField.GetValue(body), System.Globalization.CultureInfo.InvariantCulture); rateField.SetValue(body, value); var after = System.Convert.ToSingle(rateField.GetValue(body), System.Globalization.CultureInfo.InvariantCulture); return "{\"ok\":true,\"before\":" + before.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) + ",\"after\":" + after.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) + "}"; }))()